(()=>{
'use strict';
const canvas=document.getElementById('world'),ctx=canvas.getContext('2d',{alpha:false}),$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const W=4000,H=2800,T=32;let sw=0,sh=0,last=0,elapsed=0,toastTimer=0,saveTimer=0;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),rnd=(x,y)=>{let n=Math.sin(x*127.1+y*311.7+17.3)*43758.5453;return n-Math.floor(n)};
function resize(){const r=canvas.getBoundingClientRect();sw=canvas.width=Math.max(360,Math.floor(r.width/2));sh=canvas.height=Math.max(220,Math.floor(r.height/2));ctx.imageSmoothingEnabled=false}window.addEventListener('resize',resize);resize();
const biomes=[{name:'Mosswood Verge',base:'#59664a',alt:'#626e50',deep:'#414d3c',leaf:'#818353',path:'#9b9060'},{name:'Sallowfen',base:'#555d43',alt:'#606449',deep:'#39483d',leaf:'#868154',path:'#91865c'},{name:'The Quiet Mile',base:'#777354',alt:'#827a5b',deep:'#545640',leaf:'#928557',path:'#b1a16e'},{name:'Bracken Fields',base:'#77794d',alt:'#858052',deep:'#5c6242',leaf:'#a09159',path:'#b5a16b'},{name:'Cinder Coast',base:'#696c51',alt:'#737354',deep:'#4e5948',leaf:'#85825a',path:'#b5a16b'}];
function biomeAt(x,y){const nx=x/W,ny=y/H;if(nx>.70&&ny<.53)return biomes[1];if(nx>.68&&ny>.65)return biomes[4];if(ny>.69)return biomes[3];if(nx>.37&&nx<.67&&ny>.32&&ny<.7)return biomes[2];return biomes[0]}
const landmarks=[
{id:'hearth',name:'Wayfarer’s Hearth',kind:'hearth',x:1980,y:1410,desc:'A half-fallen waystation, its old fire still warm beneath the ash.',icon:'⌂'},
{id:'bell',name:'The Cracked Bell',kind:'story',x:2680,y:1040,desc:'A leaning bell tower watches the fen. Its rope stirs though there is no wind.',icon:'♧'},
{id:'chapel',name:'Chapel of Small Mercies',kind:'church',x:1300,y:2030,desc:'A moss-eaten chapel with a dry candle waiting on its altar.',icon:'✧'},
{id:'village',name:'Gannet’s Rest',kind:'village',x:3030,y:1840,desc:'An abandoned hamlet. One window glows with a stubborn amber light.',icon:'⌂'},
{id:'crypt',name:'The Silt Crypt',kind:'crypt',x:3410,y:740,desc:'Stone steps descend beneath a tree split by lightning.',icon:'▽'},
{id:'cave',name:'Mothglass Hollow',kind:'cave',x:600,y:780,desc:'A cave mouth glittering with pale mineral veins.',icon:'◒'},
{id:'spring',name:'Saint Orra’s Spring',kind:'spring',x:980,y:1560,desc:'Clear water gathers in a bowl of yellowed stone.',icon:'◉'},
{id:'watch',name:'Rookwatch',kind:'ruin',x:2250,y:2170,desc:'A ruined watch post. The old road is visible from its broken steps.',icon:'⌑'}];
const saved=(()=>{try{return JSON.parse(localStorage.getItem('hollowmere-save')||'{}')}catch{return {}})();
const state={x:saved.x||1980,y:saved.y||1410,dir:{x:0,y:1},hp:100,maxHp:100,mana:60,maxMana:60,grace:saved.grace||0,level:saved.level||1,xp:saved.xp||0,points:saved.points||0,stats:saved.stats||{strength:1,endurance:1,vitality:1},gold:saved.gold||18,inventory:saved.inventory||[{name:'Wayfarer’s blade',weight:2,rarity:'Common',type:'weapon'},{name:'Bitterleaf tonic',weight:.3,rarity:'Common',type:'potion',count:2},{name:'Fen glass',weight:.2,rarity:'Rare',type:'material',count:1}],bag:saved.bag||false,discovered:saved.discovered||['hearth'],divine:saved.divine||false,completed:saved.completed||[],kills:saved.kills||0,workers:saved.workers||0,buildings:saved.buildings||[],activeQuest:'bell',time:0};
let keys={},joystick={x:0,y:0,active:false},enemies=[],projectiles=[],particles=[],chests=[],drops=[],effects=[],weather=[],nearby=null,attackCd=0,spellCd=0,invuln=0,shake=0;
function save(){const s={x:state.x,y:state.y,grace:state.grace,level:state.level,xp:state.xp,points:state.points,stats:state.stats,gold:state.gold,inventory:state.inventory,bag:state.bag,discovered:state.discovered,divine:state.divine,completed:state.completed,kills:state.kills,workers:state.workers,buildings:state.buildings};localStorage.setItem('hollowmere-save',JSON.stringify(s))}
function toast(msg){const e=$('#toast');e.textContent=msg;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2350)}
function gainXP(n){state.xp+=n;if(state.xp>=state.level*80){state.xp-=state.level*80;state.level++;state.points+=2;state.maxHp+=8;state.hp=state.maxHp;state.maxMana+=4;state.mana=state.maxMana;toast(`Level ${state.level} · two attribute points earned`)}save()}
function initWorld(){for(let i=0;i<34;i++){let x=160+rnd(i,1)*(W-320),y=180+rnd(i,3)*(H-360);let b=biomeAt(x,y);let type=(i%7===0)?'stalker':(i%4===0?'mireling':'mosswolf');if(dist({x,y},state)>340)enemies.push({x,y,hp:type==='stalker'?48:30,max:type==='stalker'?48:30,type,aggro:false,hit:0,phase:rnd(i,9)*6,home:{x,y}})}
for(let i=0;i<17;i++){let x=220+rnd(i,12)*(W-440),y=200+rnd(i,18)*(H-400);if(landmarks.some(l=>Math.hypot(l.x-x,l.y-y)<190))continue;chests.push({x,y,opened:false,rare:rnd(i,24)>.72})}for(let i=0;i<85;i++)weather.push({x:rnd(i,33)*sw,y:rnd(i,55)*sh,v:25+rnd(i,44)*55,len:3+rnd(i,7)*5,a:.07+rnd(i,18)*.12})}
initWorld();
function tile(x,y){const bx=Math.floor(x/T),by=Math.floor(y/T),b=biomeAt(x*T+16,y*T+16),r=rnd(bx,by);let c=r>.76?b.alt:b.base;ctx.fillStyle=c;ctx.fillRect(x*T,y*T,T,T);if(r>.54){ctx.fillStyle=b.deep;ctx.fillRect(x*T+Math.floor(r*21),y*T+Math.floor(r*13),2,2)}if(r>.84){ctx.fillStyle='#b4a265';ctx.fillRect(x*T+6, y*T+19,2,1)}
// faint footpaths weave toward the old road
const wx=x*T+16,wy=y*T+16;const road=Math.abs(wy-(1450+Math.sin(wx/410)*185))<27||Math.abs(wx-(2050+Math.sin(wy/370)*210))<24;if(road){ctx.fillStyle=b.path;ctx.globalAlpha=.22;ctx.fillRect(x*T,y*T,T,T);ctx.globalAlpha=1;if(r>.65){ctx.fillStyle='#c0aa71';ctx.fillRect(x*T+9,y*T+8,4,2)}}}
function drawPlant(x,y,type,size,phase){const sway=Math.sin(elapsed*1.1+phase)*1.2;ctx.save();ctx.translate(x,y);if(type==='tree'){ctx.fillStyle='#303c31';ctx.fillRect(-2,1,5,8);ctx.fillStyle='#394735';ctx.fillRect(-9,-7+sway,18,11);ctx.fillStyle='#4b593d';ctx.fillRect(-7,-11+sway,14,9);ctx.fillStyle='#68714a';ctx.fillRect(-4,-12+sway,6,3);ctx.fillStyle='#898352';ctx.fillRect(-8,-5+sway,3,2);ctx.fillRect(4,-9+sway,3,2)}else if(type==='reed'){ctx.fillStyle='#9b9257';ctx.fillRect(-1,-8+sway,2,9);ctx.fillRect(-5,-6-sway,2,7);ctx.fillRect(4,-7+sway,2,8);ctx.fillStyle='#666b42';ctx.fillRect(-5,0,10,2)}else if(type==='stump'){ctx.fillStyle='#53513a';ctx.fillRect(-5,-3,10,7);ctx.fillStyle='#938456';ctx.fillRect(-4,-4,8,2)}else{ctx.fillStyle='#526046';ctx.fillRect(-4,-2+sway,8,4);ctx.fillStyle='#838052';ctx.fillRect(-2,-4+sway,4,3);ctx.fillStyle='#d0b977';ctx.fillRect(1,-5+sway,1,1)}ctx.restore()}
function solidAt(x,y){if(x<12||y<12||x>W-12||y>H-12)return true;let bx=Math.floor(x/T),by=Math.floor(y/T),r=rnd(bx,by);const b=biomeAt(x,y);if(r>.88)return Math.hypot((x%T)-16,(y%T)-16)<10;for(const l of landmarks){if(l.kind==='hearth'&&Math.abs(x-l.x)<60&&Math.abs(y-l.y)<42)return false}return false}

function drawLandmark(l,cx,cy){let x=l.x-cx,y=l.y-cy;ctx.save();ctx.translate(Math.round(x),Math.round(y));if(l.kind==='hearth'){ctx.fillStyle='#444638';ctx.fillRect(-42,-24,84,48);ctx.fillStyle='#777052';ctx.fillRect(-36,-20,72,39);ctx.fillStyle='#4b4c3b';ctx.fillRect(-25,-15,51,29);ctx.fillStyle='#aea06c';ctx.fillRect(-17,-8,34,18);ctx.fillStyle='#443d30';ctx.fillRect(-12,-5,24,15);ctx.fillStyle='#d49353';ctx.fillRect(-4,1,8,7);ctx.fillStyle='#e7c477';ctx.globalAlpha=.35+Math.sin(elapsed*3)*.1;ctx.beginPath();ctx.arc(0,3,21,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#b9a875';ctx.fillRect(-34,-21,8,5);ctx.fillRect(25,15,12,4)}else if(l.kind==='story'){ctx.fillStyle='#4a4b3b';ctx.fillRect(-24,-21,48,42);ctx.fillStyle='#85805e';ctx.fillRect(-20,-18,40,35);ctx.fillStyle='#53513d';ctx.fillRect(-12,-12,24,28);ctx.fillStyle='#a89a69';ctx.fillRect(-3,-29,6,32);ctx.fillRect(-10,-24,20,4);ctx.fillStyle='#d2ba76';ctx.fillRect(-2,-24,4,13);ctx.fillStyle='#bc8c55';ctx.fillRect(-5,5,10,14)}else if(l.kind==='church'||l.kind==='village'||l.kind==='ruin'){ctx.fillStyle='#45483a';ctx.fillRect(-30,-20,60,42);ctx.fillStyle='#887f5d';ctx.fillRect(-26,-17,52,35);ctx.fillStyle='#524d3b';ctx.fillRect(-17,-12,33,23);ctx.fillStyle='#b3a36a';ctx.fillRect(-4,-7,8,15);ctx.fillRect(-29,-20,11,4);ctx.fillRect(17,14,9,4);if(l.kind==='church'){ctx.fillStyle='#c7a862';ctx.fillRect(-2,-24,4,10);ctx.fillRect(-5,-21,10,3)}if(l.kind==='village'){ctx.fillStyle='#dca15b';ctx.globalAlpha=.9;ctx.fillRect(9,-3,6,7);ctx.globalAlpha=1}}else if(l.kind==='crypt'||l.kind==='cave'){ctx.fillStyle='#434739';ctx.fillRect(-29,-18,58,35);ctx.fillStyle='#777654';ctx.fillRect(-23,-14,46,26);ctx.fillStyle='#31382f';ctx.fillRect(-14,-9,28,21);ctx.fillStyle='#9b925e';ctx.fillRect(-18,-12,4,4);ctx.fillRect(14,-12,4,4);if(l.kind==='crypt'){ctx.fillStyle='#b4a36a';ctx.fillRect(-22,-18,44,4)}}else{ctx.fillStyle='#5b5b43';ctx.beginPath();ctx.ellipse(0,0,26,17,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#85825a';ctx.beginPath();ctx.ellipse(0,0,18,11,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9db198';ctx.beginPath();ctx.ellipse(0,1,11,6,0,0,Math.PI*2);ctx.fill()}
if(state.discovered.includes(l.id)){ctx.fillStyle='#e2d38e';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('✦',0,-32)}ctx.restore()}
function drawChest(c,cx,cy){if(c.opened)return;let x=c.x-cx,y=c.y-cy;ctx.fillStyle='rgba(20,25,19,.25)';ctx.fillRect(x-9,y+6,19,3);ctx.fillStyle=c.rare?'#788253':'#74563d';ctx.fillRect(x-8,y-5,16,11);ctx.fillStyle=c.rare?'#aab278':'#a48a56';ctx.fillRect(x-8,y-5,16,3);ctx.fillStyle='#d5bc71';ctx.fillRect(x-1,y-2,3,4);ctx.fillStyle='#514232';ctx.fillRect(x-7,y+3,14,2)}
function drawEnemy(e,cx,cy){let x=e.x-cx,y=e.y-cy;ctx.save();ctx.translate(x,y);let bob=Math.sin(elapsed*5+e.phase)*1.3;ctx.fillStyle='rgba(19,24,18,.3)';ctx.beginPath();ctx.ellipse(0,6,9,4,0,0,Math.PI*2);ctx.fill();ctx.translate(0,bob);if(e.type==='stalker'){ctx.fillStyle='#665540';ctx.fillRect(-8,-8,16,14);ctx.fillStyle='#9a8157';ctx.fillRect(-5,-11,10,7);ctx.fillStyle='#c5a468';ctx.fillRect(-4,-7,2,2);ctx.fillRect(3,-7,2,2);ctx.fillStyle='#494b39';ctx.fillRect(-11,-1,4,6);ctx.fillRect(7,-1,4,6)}else if(e.type==='mireling'){ctx.fillStyle='#4c684c';ctx.fillRect(-7,-8,14,13);ctx.fillStyle='#89905a';ctx.fillRect(-5,-10,10,7);ctx.fillStyle='#ddc17a';ctx.fillRect(-4,-6,2,2);ctx.fillRect(3,-6,2,2);ctx.fillStyle='#414938';ctx.fillRect(-9,2,5,5);ctx.fillRect(5,2,5,5)}else{ctx.fillStyle='#676d4a';ctx.fillRect(-8,-6,16,11);ctx.fillRect(-5,-10,10,7);ctx.fillStyle='#c5a35b';ctx.fillRect(-4,-7,2,2);ctx.fillRect(3,-7,2,2);ctx.fillStyle='#52513c';ctx.fillRect(-11,-3,4,5);ctx.fillRect(7,-3,4,5)}if(e.hp<e.max){ctx.fillStyle='#252a21';ctx.fillRect(-9,-15,18,2);ctx.fillStyle='#cf8760';ctx.fillRect(-9,-15,18*e.hp/e.max,2)}ctx.restore()}
function drawPlayer(cx,cy){let x=sw/2,y=sh/2;ctx.save();ctx.translate(x,y);let moving=Math.abs(inputX())+Math.abs(inputY())>.1,bob=moving?Math.sin(elapsed*13)*1.5:Math.sin(elapsed*2)*.5;ctx.fillStyle='rgba(15,21,16,.4)';ctx.beginPath();ctx.ellipse(0,7,9,4,0,0,Math.PI*2);ctx.fill();ctx.translate(0,bob);if(invuln>0&&Math.floor(elapsed*18)%2===0)ctx.globalAlpha=.45;ctx.fillStyle='#49463a';ctx.fillRect(-6,-8,12,13);ctx.fillStyle='#68714c';ctx.fillRect(-6,-6,12,9);ctx.fillStyle='#ba9f67';ctx.fillRect(-5,-12,10,7);ctx.fillStyle='#dbc683';ctx.fillRect(-4,-13,8,3);ctx.fillStyle='#55533d';ctx.fillRect(-6,3,5,5);ctx.fillRect(1,3,5,5);let dx=state.dir.x,dy=state.dir.y;ctx.fillStyle='#b9b28a';ctx.fillRect(dx*8-1,dy*8-1,3,3);ctx.fillStyle='#d6c07a';ctx.fillRect(dx*8+2,dy*8-2,2,6);ctx.restore()}
function drawAtmosphere(){// soft drifting pollen and fine rain
ctx.save();ctx.globalAlpha=.14;for(let i=0;i<20;i++){let x=(rnd(i,91)*sw+elapsed*(2+i%4)*3)%sw,y=(rnd(i,77)*sh+elapsed*(1+i%3)*2)%sh;ctx.fillStyle=i%3?'#d7c77f':'#c6cfa1';ctx.fillRect(x,y,1,1)}ctx.restore();if(biomeAt(state.x,state.y)===biomes[1]){ctx.fillStyle='rgba(151,168,132,.035)';ctx.fillRect(0,0,sw,sh)}if(state.time%80<35){ctx.strokeStyle='rgba(214,221,183,.12)';ctx.lineWidth=1;for(let i=0;i<30;i++){let x=(rnd(i,72)*sw+elapsed*30)%sw,y=(rnd(i,43)*sh+elapsed*90)%sh;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-2,y+5);ctx.stroke()}}}
function render(){const cx=clamp(state.x-sw/2,0,W-sw),cy=clamp(state.y-sh/2,0,H-sh);ctx.save();if(shake>0){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake*=.82}let tx0=Math.floor(cx/T),ty0=Math.floor(cy/T),tx1=Math.ceil((cx+sw)/T),ty1=Math.ceil((cy+sh)/T);for(let y=ty0;y<=ty1;y++)for(let x=tx0;x<=tx1;x++)tile(x,y);for(let y=ty0;y<=ty1;y++)for(let x=tx0;x<=tx1;x++){let r=rnd(x,y),wx=x*T+16,wy=y*T+16,b=biomeAt(wx,wy);if(r>.79){let type=(b===biomes[1]&&r>.91)?'reed':r>.96?'stump':'tree';drawPlant(wx-cx,wy-cy,type,1,r*7)}else if(r>.67)drawPlant(wx-cx,wy-cy,'grass',1,r*8)}for(const l of landmarks)if(Math.abs(l.x-state.x)<sw&&Math.abs(l.y-state.y)<sh)drawLandmark(l,cx,cy);for(const c of chests)if(Math.abs(c.x-state.x)<sw&&Math.abs(c.y-state.y)<sh)drawChest(c,cx,cy);for(const d of drops){ctx.fillStyle=d.kind==='coin'?'#dbc26f':'#9ba577';ctx.fillRect(d.x-cx-3,d.y-cy-3,6,6);ctx.fillStyle='#ebe0a6';ctx.fillRect(d.x-cx-1,d.y-cy-4,2,2)}for(const e of enemies)if(e.hp>0&&Math.abs(e.x-state.x)<sw&&Math.abs(e.y-state.y)<sh)drawEnemy(e,cx,cy);for(const p of projectiles){ctx.fillStyle=p.kind==='ember'?'#f0a563':'#e9d691';ctx.globalAlpha=.5;ctx.beginPath();ctx.arc(p.x-cx,p.y-cy,p.r*2.2,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=p.kind==='ember'?'#ffd18a':'#eee0a1';ctx.fillRect(p.x-cx-p.r,p.y-cy-p.r,p.r*2,p.r*2)}for(const p of particles){ctx.globalAlpha=clamp(p.life,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x-cx,p.y-cy,p.size,p.size)}ctx.globalAlpha=1;drawPlayer(cx,cy);for(const e of effects){ctx.strokeStyle=e.color;ctx.globalAlpha=1-e.t/e.max;ctx.lineWidth=2;ctx.beginPath();ctx.arc(sw/2+e.x,sh/2+e.y,e.r*e.t/e.max,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=1;drawAtmosphere();ctx.restore();renderHUD();}

function inputX(){return (keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0)+joystick.x}function inputY(){return (keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0)+joystick.y}
function particlesAt(x,y,color,n=8){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,v=18+Math.random()*65;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.45+Math.random()*.38,size:1+Math.random()*2,color})}}
function strike(){if(attackCd>0)return;attackCd=.42;let target=enemies.filter(e=>e.hp>0&&Math.hypot(e.x-state.x,e.y-state.y)<64&&((e.x-state.x)*state.dir.x+(e.y-state.y)*state.dir.y)>-8).sort((a,b)=>dist(a,state)-dist(b,state))[0];effects.push({x:state.dir.x*20,y:state.dir.y*20,r:22,t:0,max:.23,color:'#e6d08b'});if(target){let dmg=17+state.stats.strength*4;target.hp-=dmg;target.hit=.2;target.aggro=true;shake=2.4;particlesAt(target.x,target.y,'#d7c581',7);if(target.hp<=0){state.kills++;let xp=target.type==='stalker'?28:18;gainXP(xp);drops.push({x:target.x,y:target.y,kind:Math.random()>.62?'coin':'moss'});toast(`Felled ${target.type==='stalker'?'a hollow stalker':target.type} · +${xp} insight`)}}}
function castSpell(){if(spellCd>0)return;if(state.mana<12){toast('Not enough focus · let your mana return');return}state.mana-=12;spellCd=.68;projectiles.push({x:state.x+state.dir.x*14,y:state.y+state.dir.y*14,vx:state.dir.x*310,vy:state.dir.y*310,r:4,life:1.15,kind:'ember',damage:26+state.level*2});particlesAt(state.x+state.dir.x*14,state.y+state.dir.y*14,'#eeb977',4);}
function divinePulse(){if(!state.divine||state.grace<20){toast('A steadier faith is needed to call on grace');return}if(spellCd>0)return;spellCd=.8;state.grace-=20;let hit=0;for(const e of enemies)if(e.hp>0&&dist(e,state)<94){e.hp-=24;e.aggro=true;hit++;particlesAt(e.x,e.y,'#e3cf8a',9);if(e.hp<=0){state.kills++;gainXP(18)}}effects.push({x:0,y:0,r:95,t:0,max:.4,color:'#e8d590'});toast(hit?`Mercy answers · ${hit} foe${hit===1?'':'s'} struck`:'Mercy answers, though no foe is near');}
function getNearby(){let best=null,bd=Infinity;for(const l of landmarks){let d=dist(l,state);if(d<74&&d<bd){best={type:'landmark',obj:l,d};bd=d}}for(const c of chests)if(!c.opened){let d=dist(c,state);if(d<52&&d<bd){best={type:'chest',obj:c,d};bd=d}}return best}
function discover(l){if(!state.discovered.includes(l.id)){state.discovered.push(l.id);toast(`Discovered · ${l.name}`);gainXP(12)}if(l.id==='bell'&&state.activeQuest==='bell'){state.activeQuest='crypt';toast('The bell is cracked clean through. Find what silenced it below the fen.')}if(l.id==='crypt'&&state.activeQuest==='crypt'){state.activeQuest='return';if(!state.inventory.some(i=>i.name==='Bell clapper'))state.inventory.push({name:'Bell clapper',weight:2,rarity:'Unique',type:'quest'});toast('The clapper is here, black with old fen water. Take it back to the Hearth.')}if(l.id==='hearth'&&state.activeQuest==='return'){state.activeQuest='done';if(!state.completed.includes('bell'))state.completed.push('bell');state.gold+=45;state.grace+=12;gainXP(100);toast('The bell remembers its voice · 45 crowns, 12 grace, 100 insight') }save()}
function interact(){nearby=getNearby();if(!nearby){const npc=nearestNpc();if(npc&&npc.d<74){useNpc(npc);return}toast('Nothing close enough to reach');return}if(nearby.type==='chest'){let c=nearby.obj;c.opened=true;let coin=c.rare?24+Math.floor(Math.random()*22):8+Math.floor(Math.random()*15);state.gold+=coin;let item=c.rare?{name:'Fenward charm',weight:.2,rarity:'Rare',type:'charm'}:{name:'Moss-cured hide',weight:1,rarity:'Common',type:'material'};state.inventory.push(item);gainXP(8);particlesAt(c.x,c.y,'#e0c775',12);toast(`Cache opened · ${coin} crowns · ${item.name}`);save();return}const l=nearby.obj;discover(l);if(l.kind==='church'){openPanel('growth');return}if(l.kind==='hearth'){openPanel('hearth');return}if(l.kind==='village'){openPanel('journal');toast('A thin curl of smoke rises from the baker’s chimney');return}toast(l.name+' — '+l.desc)}
function nearestNpc(){let list=[{x:2018,y:1435,id:'mara',name:'Mara, the keeper'},{x:3060,y:1850,id:'tovin',name:'Tovin, the last baker'}];let best=null;for(let n of list){let d=dist(n,state);if(!best||d<best.d)best={...n,d}}return best}
