;ctx.fill();ctx.fillStyle='#9db198';ctx.beginPath();ctx.ellipse(0,1,11,6,0,0,Math.PI*2);ctx.fill()}if(state.discovered.includes(l.id)){ctx.fillStyle='#e2d38e';ctx.font='9px monospace';ctx.textAlign='center';ctx.fillText('✦',0,-32)}ctx.restore()}
function drawChest(c,cx,cy){if(c.opened)return;let x=c.x-cx,y=c.y-cy;ctx.fillStyle='rgba(20,25,19,.25)';ctx.fillRect(x-9,y+6,19,3);ctx.fillStyle=c.rare?'#788253':'#74563d';ctx.fillRect(x-8,y-5,16,11);ctx.fillStyle=c.rare?'#aab278':'#a48a56';ctx.fillRect(x-8,y-5,16,3);ctx.fillStyle='#d5bc71';ctx.fillRect(x-1,y-2,3,4);ctx.fillStyle='#514232';ctx.fillRect(x-7,y+3,14,2)}
function drawEnemy(e,cx,cy){let x=e.x-cx,y=e.y-cy;ctx.save();ctx.translate(x,y);ctx.fillStyle='rgba(19,24,18,.3)';ctx.beginPath();ctx.ellipse(0,6,9,4,0,0,Math.PI*2);ctx.fill();ctx.translate(0,Math.sin(elapsed*5+e.phase)*1.3);if(e.type==='stalker'){ctx.fillStyle='#665540';ctx.fillRect(-8,-8,16,14);ctx.fillStyle='#9a8157';ctx.fillRect(-5,-11,10,7);ctx.fillStyle='#c5a468';ctx.fillRect(-4,-7,2,2);ctx.fillRect(3,-7,2,2);ctx.fillStyle='#494b39';ctx.fillRect(-11,-1,4,6);ctx.fillRect(7,-1,4,6)}else if(e.type==='mireling'){ctx.fillStyle='#4c684c';ctx.fillRect(-7,-8,14,13);ctx.fillStyle='#89905a';ctx.fillRect(-5,-10,10,7);ctx.fillStyle='#ddc17a';ctx.fillRect(-4,-6,2,2);ctx.fillRect(3,-6,2,2);ctx.fillStyle='#414938';ctx.fillRect(-9,2,5,5);ctx.fillRect(5,2,5,5)}else{ctx.fillStyle='#676d4a';ctx.fillRect(-8,-6,16,11);ctx.fillRect(-5,-10,10,7);ctx.fillStyle='#c5a35b';ctx.fillRect(-4,-7,2,2);ctx.fillRect(3,-7,2,2);ctx.fillStyle='#52513c';ctx.fillRect(-11,-3,4,5);ctx.fillRect(7,-3,4,5)}if(e.hp<e.max){ctx.fillStyle='#252a21';ctx.fillRect(-9,-15,18,2);ctx.fillStyle='#cf8760';ctx.fillRect(-9,-15,18*e.hp/e.max,2)}ctx.restore()}
function inputX(){return (keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0)+joystick.x}function inputY(){return (keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0)+joystick.y}
function drawPlayer(){ctx.save();ctx.translate(sw/2,sh/2);ctx.fillStyle='rgba(15,21,16,.4)';ctx.beginPath();ctx.ellipse(0,7,9,4,0,0,Math.PI*2);ctx.fill();let moving=Math.abs(inputX())+Math.abs(inputY())>.1;ctx.translate(0,moving?Math.sin(elapsed*13)*1.5:Math.sin(elapsed*2)*.5);if(invuln>0&&Math.floor(elapsed*18)%2===0)ctx.globalAlpha=.45;ctx.fillStyle='#49463a';ctx.fillRect(-6,-8,12,13);ctx.fillStyle='#68714c';ctx.fillRect(-6,-6,12,9);ctx.fillStyle='#ba9f67';ctx.fillRect(-5,-12,10,7);ctx.fillStyle='#dbc683';ctx.fillRect(-4,-13,8,3);ctx.fillStyle='#55533d';ctx.fillRect(-6,3,5,5);ctx.fillRect(1,3,5,5);ctx.fillStyle='#b9b28a';ctx.fillRect(state.dir.x*8-1,state.dir.y*8-1,3,3);ctx.fillStyle='#d6c07a';ctx.fillRect(state.dir.x*8+2,state.dir.y*8-2,2,6);ctx.restore()}

function render(){const cx=clamp(state.x-sw/2,0,W-sw),cy=clamp(state.y-sh/2,0,H-sh);ctx.save();if(shake>0){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake*=.82}let x0=Math.floor(cx/T),y0=Math.floor(cy/T),x1=Math.ceil((cx+sw)/T),y1=Math.ceil((cy+sh)/T);for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++)tile(x,y);for(let y=y0;y<=y1;y++)for(let x=x0;x<=x1;x++){let r=rnd(x,y),wx=x*T+16,wy=y*T+16,b=biomeAt(wx,wy);if(r>.79)drawPlant(wx-cx,wy-cy,b===biomes[1]&&r>.91?'reed':r>.96?'stump':'tree',r*7);else if(r>.67)drawPlant(wx-cx,wy-cy,'grass',r*8)}for(const l of landmarks)if(Math.abs(l.x-state.x)<sw&&Math.abs(l.y-state.y)<sh)drawLandmark(l,cx,cy);for(const c of chests)if(Math.abs(c.x-state.x)<sw&&Math.abs(c.y-state.y)<sh)drawChest(c,cx,cy);for(const d of drops){ctx.fillStyle=d.kind==='coin'?'#dbc26f':'#9ba577';ctx.fillRect(d.x-cx-3,d.y-cy-3,6,6);ctx.fillStyle='#ebe0a6';ctx.fillRect(d.x-cx-1,d.y-cy-4,2,2)}for(const e of enemies)if(e.hp>0&&Math.abs(e.x-state.x)<sw&&Math.abs(e.y-state.y)<sh)drawEnemy(e,cx,cy);for(const p of projectiles){ctx.fillStyle=p.kind==='ember'?'#f0a563':'#e9d691';ctx.globalAlpha=.5;ctx.beginPath();ctx.arc(p.x-cx,p.y-cy,p.r*2.2,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle=p.kind==='ember'?'#ffd18a':'#eee0a1';ctx.fillRect(p.x-cx-p.r,p.y-cy-p.r,p.r*2,p.r*2)}for(const p of particles){ctx.globalAlpha=clamp(p.life,0,1);ctx.fillStyle=p.color;ctx.fillRect(p.x-cx,p.y-cy,p.size,p.size)}ctx.globalAlpha=1;drawPlayer();for(const e of effects){ctx.strokeStyle=e.color;ctx.globalAlpha=1-e.t/e.max;ctx.lineWidth=2;ctx.beginPath();ctx.arc(sw/2+e.x,sh/2+e.y,e.r*e.t/e.max,0,Math.PI*2);ctx.stroke()}ctx.globalAlpha=1;ctx.globalAlpha=.14;for(let i=0;i<20;i++){let x=(rnd(i,91)*sw+elapsed*(2+i%4)*3)%sw,y=(rnd(i,77)*sh+elapsed*(1+i%3)*2)%sh;ctx.fillStyle=i%3?'#d7c77f':'#c6cfa1';ctx.fillRect(x,y,1,1)}ctx.globalAlpha=1;if(biomeAt(state.x,state.y)===biomes[1]){ctx.fillStyle='rgba(151,168,132,.035)';ctx.fillRect(0,0,sw,sh)}if(state.time%80<35){ctx.strokeStyle='rgba(214,221,183,.12)';ctx.lineWidth=1;for(let i=0;i<30;i++){let x=(rnd(i,72)*sw+elapsed*30)%sw,y=(rnd(i,43)*sh+elapsed*90)%sh;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-2,y+5);ctx.stroke()}}ctx.restore();updateHud()}
function particlesAt(x,y,color,n=8){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,v=18+Math.random()*65;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.45+Math.random()*.38,size:1+Math.random()*2,color})}
function strike(){if(attackCd>0)return;attackCd=.42;let target=enemies.filter(e=>e.hp>0&&dist(e,state)<64&&((e.x-state.x)*state.dir.x+(e.y-state.y)*state.dir.y)>-8).sort((a,b)=>dist(a,state)-dist(b,state))[0];effects.push({x:state.dir.x*20,y:state.dir.y*20,r:22,t:0,max:.23,color:'#e6d08b'});if(target){target.hp-=17+state.stats.strength*4;target.hit=.2;target.aggro=true;shake=2.4;particlesAt(target.x,target.y,'#d7c581',7);if(target.hp<=0){state.kills++;let xp=target.type==='stalker'?28:18;gainXP(xp);drops.push({x:target.x,y:target.y,kind:Math.random()>.62?'coin':'moss'});toast(`Felled ${target.type==='stalker'?'a hollow stalker':target.type} · +${xp} insight`)}}}
function castSpell(){if(spellCd>0)return;if(state.mana<12){toast('Not enough focus · let your mana return');return}state.mana-=12;spellCd=.68;projectiles.push({x:state.x+state.dir.x*14,y:state.y+state.dir.y*14,vx:state.dir.x*310,vy:state.dir.y*310,r:4,life:1.15,kind:'ember',damage:26+state.level*2});particlesAt(state.x+state.dir.x*14,state.y+state.dir.y*14,'#eeb977',4)}
function divinePulse(){if(!state.divine||state.grace<20){toast('A steadier faith is needed to call on grace');return}if(spellCd>0)return;spellCd=.8;state.grace-=20;let hit=0;for(const e of enemies)if(e.hp>0&&dist(e,state)<94){e.hp-=24;e.aggro=true;hit++;particlesAt(e.x,e.y,'#e3cf8a',9);if(e.hp<=0){state.kills++;gainXP(18)}}effects.push({x:0,y:0,r:95,t:0,max:.4,color:'#e8d590'});toast(hit?`Mercy answers · ${hit} foe${hit===1?'':'s'} struck`:'Mercy answers, though no foe is near')}
function getNearby(){let best=null,bd=Infinity;for(const l of landmarks){let d=dist(l,state);if(d<74&&d<bd){best={type:'landmark',obj:l,d};bd=d}}for(const c of chests)if(!c.opened){let d=dist(c,state);if(d<52&&d<bd){best={type:'chest',obj:c,d};bd=d}}return best}
function discover(l){if(!state.discovered.includes(l.id)){state.discovered.push(l.id);toast(`Discovered · ${l.name}`);gainXP(12)}if(l.id==='bell'&&state.activeQuest==='bell'){state.activeQuest='crypt';toast('The bell is cracked clean through. Find what silenced it below the fen.')}if(l.id==='crypt'&&state.activeQuest==='crypt'){state.activeQuest='return';if(!state.inventory.some(i=>i.name==='Bell clapper'))state.inventory.push({name:'Bell clapper',weight:2,rarity:'Unique',type:'quest'});toast('The clapper is here, black with old fen water. Take it back to the Hearth.')}if(l.id==='hearth'&&state.activeQuest==='return'){state.activeQuest='done';if(!state.completed.includes('bell'))state.completed.push('bell');state.gold+=45;state.grace+=12;gainXP(100);toast('The bell remembers its voice · 45 crowns, 12 grace, 100 insight')}save()}
function nearestNpc(){let list=[{x:2018,y:1435,id:'mara',name:'Mara, the keeper'},{x:3060,y:1850,id:'tovin',name:'Tovin, the last baker'}],best=null;for(let n of list){let d=dist(n,state);if(!best||d<best.d)best={...n,d}}return best}
function useNpc(n){if(n.id==='mara'){toast('Mara: “The road needs hands. Set a hearth, and there may be work for all of us.”');openPanel('hearth')}else if(!state.bag&&state.gold>=45){if(confirm('Tovin offers a bottomless wayfarer’s satchel for 45 crowns. Buy it?')){state.gold-=45;state.bag=true;toast('Wayfarer’s satchel acquired · carried weight now counts as 10%');save()}}else toast(state.bag?'Tovin: “That satchel has more room than my whole bakery.”':'Tovin: “A deep-pocket satchel? Forty-five crowns, if you can spare them.”')}

function update(dt){elapsed+=dt;state.time+=dt;attackCd=Math.max(0,attackCd-dt);spellCd=Math.max(0,spellCd-dt);invuln=Math.max(0,invuln-dt);state.mana=Math.min(state.maxMana,state.mana+dt*2);if(state.divine)state.grace=Math.min(100,state.grace+dt*.018);let mx=inputX(),my=inputY(),mag=Math.hypot(mx,my);if(mag>1){mx/=mag;my/=mag}if(mag>.08){state.dir={x:mx,y:my};let speed=145+state.stats.endurance*3,nx=clamp(state.x+mx*speed*dt,18,W-18),ny=clamp(state.y+my*speed*dt,18,H-18);state.x=nx;state.y=ny}
for(const e of enemies){if(e.hp<=0)continue;e.hit=Math.max(0,e.hit-dt);let d=dist(e,state);if(d<245)e.aggro=true;else if(d>365)e.aggro=false;if(e.aggro&&d>21){let sp=e.type==='stalker'?40:48;e.x+=((state.x-e.x)/d)*sp*dt;e.y+=((state.y-e.y)/d)*sp*dt}else if(!e.aggro){e.x=e.home.x+Math.sin(elapsed*.35+e.phase)*10;e.y=e.home.y+Math.cos(elapsed*.31+e.phase)*10}if(d<20&&invuln<=0&&e.hit<=0){let dmg=e.type==='stalker'?13:8;state.hp-=Math.max(3,dmg-state.stats.endurance*1.6);invuln=.65;e.hit=.9;shake=3;particlesAt(state.x,state.y,'#d78463',5);if(state.hp<=0){state.hp=state.maxHp;state.x=1980;state.y=1410;state.gold=Math.max(0,state.gold-10);toast('You wake at the Wayfarer’s Hearth · 10 crowns lost')}}}
for(const p of projectiles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;for(const e of enemies)if(e.hp>0&&Math.hypot(p.x-e.x,p.y-e.y)<15){e.hp-=p.damage;e.aggro=true;e.hit=.2;particlesAt(e.x,e.y,'#f1bd76',9);p.life=0;shake=1.5;if(e.hp<=0){state.kills++;gainXP(e.type==='stalker'?28:18);drops.push({x:e.x,y:e.y,kind:'coin'})}break}}projectiles=projectiles.filter(p=>p.life>0);for(const d of drops)if(dist(d,state)<20){state.gold+=d.kind==='coin'?3:1;d.got=true}drops=drops.filter(d=>!d.got);for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;p.vx*=.96;p.vy*=.96}particles=particles.filter(p=>p.life>0);for(const e of effects)e.t+=dt;effects=effects.filter(e=>e.t<e.max);
nearby=getNearby();let p=$('#prompt');if(nearby){p.textContent=nearby.type==='chest'?'[ E ]  OPEN CACHE':`[ E ]  ${nearby.obj.name.toUpperCase()}`;p.classList.add('visible')}else{let n=nearestNpc();if(n&&n.d<74){p.textContent=`[ E ]  SPEAK TO ${n.name.toUpperCase()}`;p.classList.add('visible')}else p.classList.remove('visible')}if(saveTimer>8){saveTimer=0;save()}saveTimer+=dt;updateHud()}
function updateHud(){let h=state.hp/state.maxHp*100,m=state.mana/state.maxMana*100;$('#healthFill').style.width=h+'%';$('#manaFill').style.width=m+'%';$('#faithFill').style.width=state.grace+'%';$('#healthText').textContent=`${Math.ceil(state.hp)} / ${state.maxHp}`;$('#manaText').textContent=`${Math.floor(state.mana)} / ${state.maxMana}`;$('#faithText').textContent=Math.floor(state.grace);$('#level').textContent=state.level;$('#regionName').textContent=biomeAt(state.x,state.y).name;let mins=Math.floor(42+state.time*2)%60;$('#clock').textContent=`DAY ${String(1+Math.floor(state.time/240)).padStart(2,'0')} · ${String(16+Math.floor(state.time/30)%8).padStart(2,'0')}:${String(mins).padStart(2,'0')}`;let text,progress,count;if(state.activeQuest==='bell'){text='Find the cracked bell tower beyond the old road.';progress=state.discovered.includes('bell')?100:0;count=`${state.discovered.includes('bell')?1:0} / 1 DISCOVERED`}else if(state.activeQuest==='crypt'){text='Search the Silt Crypt for the tower’s missing clapper.';progress=state.discovered.includes('crypt')?70:35;count=`${state.discovered.includes('crypt')?1:0} / 1 CLAPPER`}else if(state.activeQuest==='return'){text='Bring the clapper back to the Wayfarer’s Hearth.';progress=85;count='RETURN TO THE HEARTH'}else{text='The old road has a voice again. See what else the island remembers.';progress=100;count='THREAD COMPLETE'}$('#questTitle').textContent='A Bell in the Mire';$('#questText').textContent=text;$('#questProgress').style.width=progress+'%';$('#questCount').textContent=count}
function interact(){nearby=getNearby();if(!nearby){let n=nearestNpc();if(n&&n.d<74){useNpc(n);return}toast('Nothing close enough to reach');return}if(nearby.type==='chest'){let c=nearby.obj;c.opened=true;let coin=c.rare?24+Math.floor(Math.random()*22):8+Math.floor(Math.random()*15);state.gold+=coin;let item=c.rare?{name:'Fenward charm',weight:.2,rarity:'Rare',type:'charm'}:{name:'Moss-cured hide',weight:1,rarity:'Common',type:'material'};state.inventory.push(item);gainXP(8);particlesAt(c.x,c.y,'#e0c775',12);toast(`Cache opened · ${coin} crowns · ${item.name}`);save();return}let l=nearby.obj;discover(l);if(l.kind==='church')openPanel('growth');else if(l.kind==='hearth')openPanel('hearth');else if(l.kind==='village')toast('A thin curl of smoke rises from the baker’s chimney');else toast(l.name+' — '+l.desc)}

const panel=$('#panel');function openPanel(tab){panel.classList.add('open');showTab(tab||'journal')}function closePanel(){panel.classList.remove('open')}function showTab(tab){$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let body=$('#panelBody'),title=$('#panelTitle'),eye=$('#panelEyebrow');if(tab==='journal'){eye.textContent='FIELD JOURNAL';title.textContent='The island remembers';body.innerHTML=`<p class="panel-copy">A place of old roads and second chances. The island is yours to walk; no bell will call you home.</p><div class="section-label">THE THREAD YOU FOLLOW</div><div class="quest-line"><div><strong>A Bell in the Mire</strong><small>${$('#questText').textContent}</small></div><span class="tag">${state.activeQuest==='done'?'RESOLVED':'MAIN'}</span></div><div class="section-label">FIELD NOTES · ${state.discovered.length} FOUND</div>${landmarks.map(l=>`<div class="quest-line"><div><strong>${state.discovered.includes(l.id)?l.name:'Unknown place'}</strong><small>${state.discovered.includes(l.id)?l.desc:'Walk the island to learn what lies here.'}</small></div><span class="tag">${state.discovered.includes(l.id)?'RECORDED':'?'}</span></div>`).join('')}<div class="callout">The cracked bell, the old chapel, a cave that catches the light. The roads are still there if you look for them.</div><button class="small-btn" id="journalMap">OPEN ISLAND MAP</button>`;$('#journalMap').onclick=openMap}
if(tab==='pack'){eye.textContent='WAYFARER’S PACK';title.textContent='Things worth carrying';let weight=state.inventory.reduce((a,i)=>a+(i.weight||0)*(i.count||1),0),cap=12+state.stats.strength*6,eff=weight*(state.bag?.1:1);body.innerHTML=`<div class="stat-note"><span>${state.gold} CROWNS</span><span>${eff.toFixed(1)} / ${state.bag?'∞':cap+' KG'}</span></div><div class="meter-wide"><i style="width:${state.bag?10:Math.min(100,eff/cap*100)}%"></i></div><p class="panel-copy">${state.bag?'The wayfarer’s satchel makes carried weight count as one tenth.':'Strength increases your carrying capacity. Tovin in Gannet’s Rest sells a satchel that reduces all carried weight to 10%.'}</p><div class="section-label">CARRIED</div>${state.inventory.map((i,n)=>`<div class="item-row"><div><strong>${i.name}${i.count>1?' ×'+i.count:''}</strong><small>${i.weight} kg · ${i.type}</small></div><span class="tag ${i.rarity==='Rare'?'rarity-rare':i.rarity==='Unique'?'rarity-unique':''}">${i.rarity.toUpperCase()}</span></div>`).join('')}<div class="callout">Caches and fallen creatures leave useful things behind. The satchel can be bought from Tovin at Gannet’s Rest.</div>`}
if(tab==='growth'){eye.textContent='A LIFE WITHOUT ORDERS';title.textContent='Choose who you become';let total=12+state.stats.strength*6,weight=state.inventory.reduce((a,i)=>a+i.weight*(i.count||1),0)*(state.bag?.1:1);body.innerHTML=`<p class="panel-copy">No fixed path. Spend insight earned in the wild on the attributes that suit your way of walking it.</p><div class="section-label">ATTRIBUTES · ${state.points} POINTS TO SPEND</div>${[['strength','Strength','Melee damage · carrying capacity'],['endurance','Endurance','Damage resistance · movement pace'],['vitality','Vitality','Maximum vigor · recovery']].map(([key,label,desc])=>`<div class="stat-row"><div><b>${label}</b><small class="panel-copy">${desc}</small></div><strong>${state.stats[key]}</strong><button class="small-btn" data-stat="${key}" ${state.points<1?'disabled':''}>+1</button></div>`).join('')}<div class="section-label">YOUR PATH</div><div class="callout">${state.divine?'The Chapel of Small Mercies has heard your vow. Grace returns slowly; charity and pilgrimage deepen it.':'The Chapel of Small Mercies waits in the southern fields. Pray there to open a second path beside your mana.'}</div><div class="stat-note"><span>VIGOR</span><span>${state.maxHp}</span></div><div class="stat-note"><span>FOCUS</span><span>${state.maxMana}</span></div><div class="stat-note"><span>CAPACITY</span><span>${state.bag?'∞':total+' KG'} · ${weight.toFixed(1)} KG CARRIED</span></div><div class="section-label">DIVINE ABILITIES</div><div class="item-row"><div><strong>Mercy’s Reach</strong><small>Spend 20 grace to strike nearby foes with a pulse of light.</small></div><button class="small-btn" id="divineBtn">${state.divine?'UNLOCKED':'PRAY AT CHAPEL'}</button></div><div class="item-row"><div><strong>Pilgrim’s Welcome</strong><small>Offer aid to strangers; charity earns grace and crowns.</small></div><button class="small-btn" id="charityBtn">OFFER 5 CROWNS</button></div>`;$$('[data-stat]').forEach(b=>b.onclick=()=>{if(state.points){state.stats[b.dataset.stat]++;state.points--;if(b.dataset.stat==='vitality'){state.maxHp+=12;state.hp+=12}if(b.dataset.stat==='endurance')state.maxHp+=3;save();showTab('growth')}});$('#divineBtn').onclick=()=>{if(state.divine){toast('Grace listens. Use the ✧ ability near danger.');return}if(state.discovered.includes('chapel')){state.divine=true;state.grace=Math.max(25,state.grace);toast('The chapel hears your vow · Mercy’s Reach unlocked');save();showTab('growth')}else toast('Find the Chapel of Small Mercies in the southern fields')};$('#charityBtn').onclick=()=>{if(state.gold<5){toast('You need 5 crowns to share a meal');return}state.gold-=5;state.grace=Math.min(100,state.grace+18);state.completed.includes('charity')||state.completed.push('charity');gainXP(10);toast('A meal shared · +18 grace, +10 insight');save();showTab('growth')}}
