(()=>{
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const canvas=$('#world'),ctx=canvas.getContext('2d'),mapCanvas=$('#mapCanvas'),mctx=mapCanvas.getContext('2d');
const W=2200,H=1600,saveKey='hollowmere-save';
const landmarks=[
