function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');toastTimer=2.7}
function discover(id){if(!state.discovered.includes(id)){state.discovered.push(id);const l=landmarks.find(a=>a.id===id);toast(`Recorded: ${l?.name||'a new place'}`);save();if($('#panel').classList.contains('open'))showTab('journal')}}
function setQuest(id,title,text,count){state.activeQuest=id;$('#questTitle').textContent=title;$('#questText').textContent=text;$('#questCount').textContent=count;$('#questProgress').style.width=id==='bell'?'22%':id==='crypt'?'58%':id==='return'?'82%':'100%';save()}
function updateQuest(){if(state.activeQuest==='bell'){setQuest('bell','A Bell in the Mire','Find the cracked bell tower beyond the old road.','0 / 1 DISCOVERED')}else if(state.activeQuest==='crypt'){setQuest('crypt','A Bell in the Mire','Search beneath the bell tower for what woke the mire.','1 / 2 DISCOVERED')}else if(state.activeQuest==='return'){setQuest('return','A Bell in the Mire','Carry the bell’s silence back to Gannet’s Rest.','2 / 2 DISCOVERED')}else{setQuest('done','A Bell in the Mire','The island is quieter. Your story is still your own.','THREAD COMPLETE')}}
function updateHud(){const pct=(v,m)=>`${Math.max(0,Math.round(v))} / ${m}`;$('#healthFill').style.width=`${Math.max(0,state.hp/state.maxHp*100)}%`;$('#healthText').textContent=pct(state.hp,state.maxHp);$('#manaFill').style.width=`${Math.max(0,state.mana/state.maxMana*100)}%`;$('#manaText').textContent=pct(state.mana,state.maxMana);$('#faithFill').style.width=`${Math.min(100,state.grace/50*100)}%`;$('#faithText').textContent=`${Math.floor(state.grace)} GRACE`;$('#level').textContent=state.level;const region=state.y>1070?'Southern Fields':state.x>1570?'Lanternroot Wilds':state.x>880?'Mirewood':state.x<600?'Gannet’s Rest':'Mosswood Verge';$('#regionName').textContent=region;const mins=Math.floor(state.playTime/60);$('#clock').textContent=`DAY ${String(state.day).padStart(2,'0')} · ${String(16+Math.floor(mins/60)%8).padStart(2,'0')}:${String(mins%60).padStart(2,'0')}`}
