20:function discover(id){if(!state.discovered.includes(id)){state.discovered.push(id);const l=landmarks.find(a=>a.id===id);toast(`Recorded: ${l?.name||'a new place'}`);save();if($('#panel').classList.contains('open'))showTab('journal')}}
24:function openPanel(tab){$('#panel').classList.add('open');showTab(tab||'journal')}
25:function closePanel(){$('#panel').classList.remove('open')}
26:function showTab(tab){$$('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const body=$('#panelBody'),title=$('#panelTitle'),eye=$('#panelEyebrow');
27: if(tab==='journal'){eye.textContent='FIELD JOURNAL';title.textContent='The island remembers';body.innerHTML=`<p class="panel-copy">A place of old roads and second chances. The island is yours to walk; no bell will call you home.</p><div class="section-label">THE THREAD YOU FOLLOW</div><div class="quest-line"><div><strong>${$('#questTitle').textContent}</strong><small>${$('#questText').textContent}</small></div><span class="tag">${state.activeQuest==='done'?'RESOLVED':'MAIN'}</span></div><div class="section-label">FIELD NOTES · ${state.discovered.length} FOUND</div>${landmarks.map(l=>`<div class="quest-line"><div><strong>${state.discovered.includes(l.id)?l.name:'Unknown place'}</strong><small>${state.discovered.includes(l.id)?l.desc:'Walk the island to learn what lies here.'}</small></div><span class="tag">${state.discovered.includes(l.id)?'RECORDED':'?'}</span></div>`).join('')}<div class="callout">The cracked bell, the old chapel, a cave that catches the light. The roads are still there if you look for them.</div><button class="small-btn" id="journalMap">OPEN ISLAND MAP</button>`;$('#journalMap').onclick=openMap}
28: else if(tab==='pack'){eye.textContent='WAYFARER’S PACK';title.textContent='Things worth carrying';const weight=inventoryWeight(),cap=12+state.stats.strength*6,eff=weight*(state.bag?.1:1);body.innerHTML=`<div class="stat-note"><span>${state.gold} CROWNS</span><span>${eff.toFixed(1)} / ${state.bag?'∞':cap+' KG'}</span></div><div class="meter-wide"><i style="width:${state.bag?10:Math.min(100,eff/cap*100)}%"></i></div><p class="panel-copy">${state.bag?'The wayfarer’s satchel makes carried weight count as one tenth.':'Strength increases your carrying capacity. Tovin in Gannet’s Rest sells a satchel that reduces all carried weight to 10%.'}</p><div class="section-label">CARRIED</div>${state.inventory.map(i=>`<div class="item-row"><div><strong>${i.name}${i.count>1?' ×'+i.count:''}</strong><small>${i.weight} kg · ${i.type}</small></div><span class="tag ${i.rarity==='Rare'?'rarity-rare':i.rarity==='Unique'?'rarity-unique':''}">${i.rarity.toUpperCase()}</span></div>`).join('')}<div class="callout">Caches and fallen creatures leave useful things behind. The satchel can be bought from Tovin at Gannet’s Rest.</div>`}
29: else if(tab==='growth'){eye.textContent='A LIFE WITHOUT ORDERS';title.textContent='Choose who you become';const total=12+state.stats.strength*6,weight=inventoryWeight()*(state.bag?.1:1);body.innerHTML=`<p class="panel-copy">No fixed path. Spend insight earned in the wild on the attributes that suit your way of walking it.</p><div class="section-label">ATTRIBUTES · ${state.points} POINTS TO SPEND</div>${[['strength','Strength','Melee damage · carrying capacity'],['endurance','Endurance','Damage resistance · movement pace'],['vitality','Vitality','Maximum vigor · recovery']].map(([key,label,desc])=>`<div class="stat-row"><div><b>${label}</b><small class="panel-copy">${desc}</small></div><strong>${state.stats[key]}</strong><button class="small-btn" data-stat="${key}" ${state.points<1?'disabled':''}>+1</button></div>`).join('')}<div class="section-label">YOUR PATH</div><div class="callout">${state.divine?'The Chapel of Small Mercies has heard your vow. Grace returns slowly; charity and pilgrimage deepen it.':'The Chapel of Small Mercies waits in the southern fields. Pray there to open a second path beside your mana.'}</div><div class="stat-note"><span>VIGOR</span><span>${state.maxHp}</span></div><div class="stat-note"><span>FOCUS</span><span>${state.maxMana}</span></div><div class="stat-note"><span>CAPACITY</span><span>${state.bag?'∞':total+' KG'} · ${weight.toFixed(1)} KG CARRIED</span></div><div class="section-label">DIVINE ABILITIES</div><div class="item-row"><div><strong>Mercy’s Reach</strong><small>Spend 20 grace to strike nearby foes with a pulse of light.</small></div><button class="small-btn" id="divineBtn">${state.divine?'UNLOCKED':'PRAY AT CHAPEL'}</button></div><div class="item-row"><div><strong>Pilgrim’s Welcome</strong><small>Offer aid to strangers; charity earns grace and crowns.</small></div><button class="small-btn" id="charityBtn">OFFER 5 CROWNS</button></div>`;$$('[data-stat]').forEach(b=>b.onclick=()=>{if(!state.points)return;state.points--;const k=b.dataset.stat;state.stats[k]++;if(k==='vitality'){state.maxHp+=15;state.hp+=15}if(k==='endurance')state.maxHp+=5;showTab('growth');updateHud();save()});$('#divineBtn').onclick=()=>{const d=landmarks.find(l=>l.id==='chapel');if(distance(state,d)<95){state.divine=true;discover('chapel');toast('Grace answers your prayer.')}else toast('Visit the Chapel of Small Mercies to pray.');showTab('growth');save()};$('#charityBtn').onclick=()=>{if(state.gold<5){toast('You need 5 crowns to share a meal.');return}state.gold-=5;state.grace=Math.min(100,state.grace+12);state.xp+=8;toast('A stranger accepts your kindness. +12 grace');showTab('growth');save()}}
30: else if(tab==='hearth'){eye.textContent='WAYFARER’S HEARTH';title.textContent='A place to return to';const structures=[['Waystation','A modest hall. Attracts another hand to the settlement.',30],['Forge','Assign a worker to turn salvage into useful gear.',45],['Herbalist’s lean-to','A worker tends bitterleaf and healing tonics.',38],['Warding post','A hired companion watches the Hearth.',55]];body.innerHTML=`<p class="panel-copy">Let others do the gathering. Give them a safe place, and they will make the island a little more livable.</p><div class="stat-note"><span>SETTLEMENT CROWNS</span><span>${state.gold}</span></div><div class="section-label">YOUR WORKERS · ${state.workers}</div><div class="callout">${state.workers?`${state.workers} worker${state.workers===1?'':'s'} assigned. A forge yields salvage every 60 seconds.`:'Mara keeps the fire. Build a waystation to make room for a worker.'}</div><div class="section-label">BUILD SOMETHING</div><div class="build-grid">${structures.map(([n,d,c])=>`<div class="build-card"><b>${n}</b><small>${d}</small><button class="small-btn build-btn" data-name="${n}" data-cost="${c}" ${state.gold<c||((n!=='Waystation')&&!state.workers)?'disabled':''}>BUILD · ${c}◉</button></div>`).join('')}</div><div class="section-label">PROVISIONING</div><div class="item-row"><div><strong>Rest and recover</strong><small>Return to full vigor and focus.</small></div><button class="small-btn" id="restBtn">REST · 3◉</button></div><div class="item-row"><div><strong>Share the table</strong><small>Feed a traveler and gain divine grace.</small></div><button class="small-btn" id="mealBtn">GIVE · 5◉</button></div><div class="callout">The Hearth is your base. Exploration, secrets and a dangerous island still await beyond its light.</div>`;$$('.build-btn').forEach(b=>b.onclick=()=>{const n=b.dataset.name,c=Number(b.dataset.cost);if(state.gold<c||((n!=='Waystation')&&!state.workers))return;state.gold-=c;state.buildings.push(n);if(n==='Waystation'){state.workers++;if(!state.completed.includes('settlement'))state.completed.push('settlement')}toast(`${n} raised at Gannet’s Rest.`);showTab('hearth');save()});$('#restBtn').onclick=()=>{if(state.gold<3){toast('You need 3 crowns to rest.');return}state.gold-=3;state.hp=state.maxHp;state.mana=state.maxMana;toast('You rest by the hearth.');showTab('hearth');updateHud();save()};$('#mealBtn').onclick=()=>{if(state.gold<5){toast('You need 5 crowns to share a meal.');return}state.gold-=5;state.grace=Math.min(100,state.grace+12);toast('The table is shared. +12 grace');showTab('hearth');save()}}
40:function drawLandmark(l){const p=screen(l);if(p.x< -100||p.y< -100||p.x>canvas._w+100||p.y>canvas._h+100)return;ctx.save();ctx.translate(p.x,p.y);if(l.kind==='home'){ctx.fillStyle='#3c392a';ctx.fillRect(-28,-20,56,40);ctx.fillStyle='#766344';ctx.beginPath();ctx.moveTo(-36,-20);ctx.lineTo(0,-48);ctx.lineTo(36,-20);ctx.closePath();ctx.fill();ctx.fillStyle='#d3a75d';ctx.fillRect(8,-5,9,14);ctx.fillStyle='#e2a858';ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(0,22,18,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#ffcb6e';ctx.beginPath();ctx.arc(0,21,5,0,Math.PI*2);ctx.fill()}else if(l.kind==='tower'){ctx.fillStyle='#534d3c';ctx.fillRect(-20,-8,40,52);ctx.fillStyle='#756849';ctx.fillRect(-27,-15,54,10);ctx.fillRect(-14,-45,28,30);ctx.fillStyle='#302f27';ctx.fillRect(-5,12,10,32);ctx.strokeStyle='#a99a6a';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,-39);ctx.lineTo(0,-22);ctx.stroke();ctx.fillStyle='#b9a268';ctx.beginPath();ctx.arc(0,-18,5,0,Math.PI*2);ctx.fill()}else if(l.kind==='chapel'){ctx.fillStyle='#565643';ctx.fillRect(-25,-15,50,45);ctx.fillStyle='#85805b';ctx.beginPath();ctx.moveTo(-32,-15);ctx.lineTo(0,-44);ctx.lineTo(32,-15);ctx.fill();ctx.fillStyle='#34372c';ctx.fillRect(-5,2,11,28);ctx.strokeStyle='#c2b47a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(0,-45);ctx.lineTo(0,-62);ctx.moveTo(-6,-56);ctx.lineTo(6,-56);ctx.stroke()}else if(l.kind==='cave'){ctx.fillStyle='#4c503d';ctx.beginPath();ctx.moveTo(-38,20);ctx.lineTo(-27,-20);ctx.lineTo(0,-37);ctx.lineTo(30,-18);ctx.lineTo(41,20);ctx.closePath();ctx.fill();ctx.fillStyle='#20281f';ctx.beginPath();ctx.ellipse(0,9,20,22,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b7ad67';ctx.globalAlpha=.75;ctx.beginPath();ctx.arc(0,9,5,0,Math.PI*2);ctx.fill()}else{ctx.fillStyle='#585643';ctx.fillRect(-30,-9,60,30);ctx.fillStyle='#302f27';ctx.fillRect(-19,-8,38,26);ctx.strokeStyle='#928965';ctx.lineWidth=4;ctx.strokeRect(-29,-10,58,32)}ctx.restore();if(state.discovered.includes(l.id)){ctx.fillStyle='rgba(231,214,158,.85)';ctx.font='11px DM Mono,monospace';ctx.textAlign='center';ctx.fillText(l.name,p.x,p.y-55)}}
41:function drawPerson(x,y,color,player=false){const p=screen({x,y});ctx.fillStyle='rgba(23,27,20,.42)';ctx.beginPath();ctx.ellipse(p.x,p.y+9,11,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=player?'#c9b47a':color;ctx.fillRect(p.x-7,p.y-10,14,18);ctx.fillStyle=player?'#d9c9a0':'#b9a775';ctx.beginPath();ctx.arc(p.x,p.y-13,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#38382c';ctx.fillRect(p.x-5,p.y-2,4,10);ctx.fillRect(p.x+2,p.y-2,4,10);if(player){ctx.strokeStyle='#d8d0b1';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x+7,p.y-4);ctx.lineTo(p.x+15,p.y-15);ctx.stroke()}}
49:function interact(){const target=nearby();if(!target){toast('There is nothing close enough to use.');return}if(target.kind==='tower'){discover('bell');if(state.activeQuest==='bell'){setQuest('crypt','A Bell in the Mire','Search beneath the bell tower for what woke the mire.','1 / 2 DISCOVERED');toast('A hollow sound answers from beneath the tower.');}else toast('The cracked bell gives no answer.')}else if(target.kind==='crypt'){discover('crypt');if(state.activeQuest==='crypt'){setQuest('return','A Bell in the Mire','Carry the bell’s silence back to Gannet’s Rest.','2 / 2 DISCOVERED');state.xp+=35;awardXp();toast('The crypt falls silent. Return to Gannet’s Rest.')}else toast('The crypt door rests shut in its frame.')}else if(target.kind==='chapel'){discover('chapel');state.divine=true;state.grace=Math.min(100,state.grace+18);toast('You pray. Grace answers with a warm pulse.');if($('#panel').classList.contains('open'))showTab('growth')}else if(target.kind==='cave'){discover('cave');if(!state.completed.includes('cave-cache')){state.completed.push('cave-cache');state.gold+=16;state.inventory.push({name:'Rootglass charm',weight:.1,type:'Relic',rarity:'Rare',count:1});state.xp+=18;awardXp();toast('A cache glimmers in the cave: +16 crowns, Rootglass charm.')}else toast('Only a little amber light remains.')}else if(target.kind==='home'){discover('hearth');if(state.activeQuest==='return'){setQuest('done','A Bell in the Mire','The island is quieter. Your story is still your own.','THREAD COMPLETE');state.completed.push('bell-quest');state.gold+=20;toast('The hearth welcomes you. +20 crowns · Thread complete.')}else{state.hp=state.maxHp;state.mana=state.maxMana;toast('Mara offers you warmth and a moment’s rest.')}}else if(target.kind==='tovin'){if(!state.bag){if(state.gold>=30){state.gold-=30;state.bag=true;toast('Tovin sells you a wayfarer’s satchel.')}else toast('Tovin’s satchel costs 30 crowns. Bring him more.')}else toast('Tovin nods at your well-used satchel.')}else if(target.kind==='mara'){state.hp=state.maxHp;state.mana=state.maxMana;toast('Mara: “The fire is yours, friend.”')}save();updateHud()}
